    "         des.map({ map = [[\n}}}}}}\n}----}\n}|..|}\n}|..|}\n}----}\n}}}}}}]], contents = function(m)\n    " +
    "        des.region({ region={3,3,3,3}, type=\"themed\", irregular=true,\n                         fille" +
    "d=0, joined=false });\n            local nasty_undead = { \"giant zombie\", \"ettin zombie\", \"vampire lo" +
    "rd\" };\n            local chest_spots = { { 2, 2 }, { 3, 2 }, { 2, 3 }, { 3, 3 } };\n\n            shuf" +
    "fle(chest_spots)\n            -- Guarantee an escape item inside one of the chests, to prevent\n      " +
    "      -- the hero falling in from above and becoming permanently stuck\n            -- [cf. generate_" +
    "way_out_method(sp_lev.c)].\n            -- If the escape item is made of glass or crystal, make sure " +
    "that\n            -- the chest isn't locked so that kicking it to gain access to its\n            -- c" +
    "ontents won't be necessary; otherwise retain lock state from\n            -- random creation.\n       " +
    "     -- \"pick-axe\", \"dwarvish mattock\" could be included in the list of\n            -- escape items " +
    "but don't normally generate in containers.\n            local escape_items = {\n               \"scroll" +
    " of teleportation\", \"ring of teleportation\",\n               \"wand of teleportation\", \"wand of diggin" +
    "g\"\n            };\n            local itm = obj.new(escape_items[math.random(#escape_items)]);\n       " +
    "     local itmcls = itm:class()\n            local box\n            if itmcls[ \"material\" ] == \"glass\"" +
    " then\n                  -- explicitly force chest to be unlocked\n                  box = des.object(" +
    "{ id = \"chest\", coord = chest_spots[1],\n                                    olocked = \"no\" });\n     " +
    "       else\n                  -- accept random locked/unlocked state\n                  box = des.obj" +
    "ect({ id = \"chest\", coord = chest_spots[1] });\n            end;\n            box:addcontent(itm);\n\n  " +
    "          for i = 2, #chest_spots do\n                  des.object({ id = \"chest\", coord = chest_spot" +
    "s[i] });\n            end\n\n            shuffle(nasty_undead);\n            des.monster(nasty_undead[1]" +
    ", 2, 2);\n            des.exclusion({ type = \"teleport\", region = { 2,2, 3,3 } });\n         end });\n " +
    "     end,\n   },\n\n   {\n      name = 'Twin businesses',\n      mindiff = 4, -- arbitrary\n      contents" +
    " = function()\n         -- Due to the way room connections work in mklev.c, we must guarantee\n       " +
    "  -- that the \"aisle\" between the shops touches all four walls of the\n         -- larger room. Thus " +
    "it has an extra width and height.\n         des.room({ type=\"themed\", w=9, h=5, contents = function()" +
    "\n               -- There are eight possible placements of the two shops, four of\n               -- w" +
    "hich have the vertical aisle in the center.\n               southeast = function() return percent(50)" +
    " and \"south\" or \"east\" end\n               northeast = function() return percent(50) and \"north\" or \"" +
    "east\" end\n               northwest = function() return percent(50) and \"north\" or \"west\" end\n       " +
    "        southwest = function() return percent(50) and \"south\" or \"west\" end\n               placement" +
    "s = {\n                  { lx = 1, ly = 1, rx = 4, ry = 1, lwall = \"south\", rwall = southeast() },\n  " +
    "                { lx = 1, ly = 2, rx = 4, ry = 2, lwall = \"north\", rwall = northeast() },\n          " +
    "        { lx = 1, ly = 1, rx = 5, ry = 1, lwall = southeast(), rwall = southwest() },\n              " +
    "    { lx = 1, ly = 1, rx = 5, ry = 2, lwall = southeast(), rwall = northwest() },\n                  " +
    "{ lx = 1, ly = 2, rx = 5, ry = 1, lwall = northeast(), rwall = southwest() },\n                  { lx" +
    " = 1, ly = 2, rx = 5, ry = 2, lwall = northeast(), rwall = northwest() },\n                  { lx = 2" +
    ", ly = 1, rx = 5, ry = 1, lwall = southwest(), rwall = \"south\" },\n                  { lx = 2, ly = 2" +
    ", rx = 5, ry = 2, lwall = northwest(), rwall = \"north\" }\n               }\n               ltype,rtype" +
    " = \"weapon shop\",\"armor shop\"\n               if percent(50) then\n                  ltype,rtype = rty" +
    "pe,ltype\n               end\n               shopdoorstate = function()\n                  if percent(1" +
    ") then\n                     return \"locked\"\n                  elseif percent(50) then\n              " +
    "       return \"closed\"\n                  else\n                     return \"open\"\n                  e" +
    "nd\n               end\n               p = placements[d(#placements)]\n               des.room({ type=l" +
    "type, x=p[\"lx\"], y=p[\"ly\"], w=3, h=3, filled=1, joined=false,\n                           contents = " +
    "function()\n                     des.door({ state=shopdoorstate(), wall=p[\"lwall\"] })\n               " +
    "   end\n               });\n               des.room({ type=rtype, x=p[\"rx\"], y=p[\"ry\"], w=3, h=3, fill" +
    "ed=1, joined=false,\n                           contents = function()\n                     des.door({" +
    " state=shopdoorstate(), wall=p[\"rwall\"] })\n                  end\n               });\n            end\n" +
    "         });\n      end\n   },\n\n};\n\n-- store these at global scope, they will be reinitialized in\n-- p" +
    "re_themerooms_generate\ndebug_rm_idx = nil\ndebug_fill_idx = nil\n\n-- Given a point in a themed room, e" +
    "nsure that themed room is stocked with\n-- regular room contents.\n-- With 30% chance, also give it a " +
    "random themed fill.\nfunction filler_region(x, y)\n   local rmtyp = \"ordinary\";\n   local func = nil;\n " +
    "  if (percent(30)) then\n      rmtyp = \"themed\";\n      func = themeroom_fill;\n   end\n   des.region({ " +
    "region={x,y,x,y}, type=rmtyp, irregular=true, filled=1, contents = func });\nend\n\nfunction is_eligibl" +
    "e(room, mkrm)\n   local t = type(room);\n   local diff = nh.level_difficulty();\n   if (room.mindiff ~=" +
    " nil and diff < room.mindiff) then\n      return false\n   elseif (room.maxdiff ~= nil and diff > room" +
    ".maxdiff) then\n      return false\n   end\n   if (mkrm ~= nil and room.eligible ~= nil) then\n      ret" +
    "urn room.eligible(mkrm);\n   end\n   return true\nend\n\n-- given the name of a themed room or fill, retu" +
    "rn its index in that array\nfunction lookup_by_name(name, checkfills)\n   if name == nil then\n      re" +
    "turn nil\n   end\n   if checkfills then\n      for i = 1, #themeroom_fills do\n         if themeroom_fil" +
    "ls[i].name == name then\n            return i\n         end\n      end\n   else\n      for i = 1, #themer" +
    "ooms do\n         if themerooms[i].name == name then\n            return i\n         end\n      end\n   e" +
    "nd\n   return nil\nend\n\n-- called repeatedly until the core decides there are enough rooms\nfunction th" +
    "emerooms_generate()\n   if debug_rm_idx ~= nil then\n      -- room may not be suitable for stairs/port" +
    "als, so create the \"default\"\n      -- room half of the time\n      -- (if the user specified BOTH a r" +
    "oom and a fill, presumably they are\n      -- interested in what happens when that room gets that fil" +
    "l, so don't\n      -- bother generating default-with-fill rooms as happens below)\n      local actualr" +
    "m = lookup_by_name(\"default\", false);\n      if percent(50) then\n         if is_eligible(themerooms[d" +
    "ebug_rm_idx]) then\n            actualrm = debug_rm_idx\n         else\n            pline(\"Warning: the" +
    "meroom '\"..themerooms[debug_rm_idx].name\n                  ..\"' is ineligible\")\n         end\n      e" +
    "nd\n      themerooms[actualrm].contents();\n      return\n   elseif debug_fill_idx ~= nil then\n      --" +
    " when a fill is requested but not a room, still create the \"default\"\n      -- room half of the time," +
    " and \"default with themed fill\" half of the time\n      -- (themeroom_fill will take care of guarante" +
    "eing the fill in it)\n      local actualrm = lookup_by_name(percent(50) and \"Default room with themed" +
    " fill\"\n                                                  or \"default\")\n      themerooms[actualrm].co" +
    "ntents();\n      return\n   end\n   local pick = nil;\n   local total_frequency = 0;\n   for i = 1, #them" +
    "erooms do\n      if (type(themerooms[i]) ~= \"table\") then\n         nh.impossible('themed room '..i..'" +
    " is not a table')\n      elseif is_eligible(themerooms[i], nil) then\n         -- Reservoir sampling: " +
    "select one room from the set of eligible rooms,\n         -- which may change on different levels bec" +
    "ause of level difficulty.\n         local this_frequency;\n         if (themerooms[i].frequency ~= nil" +
    ") then\n            this_frequency = themerooms[i].frequency;\n         else\n            this_frequenc" +
    "y = 1;\n         end\n         total_frequency = total_frequency + this_frequency;\n         -- avoid r" +
    "n2(0) if a room has freq 0\n         if this_frequency > 0 and nh.rn2(total_frequency) < this_frequen" +
    "cy then\n            pick = i;\n         end\n      end\n   end\n   if pick == nil then\n      nh.impossib" +
    "le('no eligible themed rooms?')\n      return\n   end\n   themerooms[pick].contents();\nend\n\n-- called b" +
    "efore any rooms are generated\nfunction pre_themerooms_generate()\n   local debug_themerm = nh.debug_t" +
    "hemerm(false)\n   local debug_fill = nh.debug_themerm(true)\n   local xtrainfo = \"\"\n   debug_rm_idx = " +
    "lookup_by_name(debug_themerm, false)\n   debug_fill_idx = lookup_by_name(debug_fill, true)\n   if debu" +
    "g_themerm ~= nil and debug_rm_idx == nil then\n      if lookup_by_name(debug_themerm, true) ~= nil th" +
    "en\n         xtrainfo = \"; it is a fill type\"\n      end\n      pline(\"Warning: themeroom '\"..debug_the" +
    "merm\n            ..\"' not found in themerooms\"..xtrainfo, true)\n   end\n   if debug_fill ~= nil and d" +
    "ebug_fill_idx == nil then\n      if lookup_by_name(debug_fill, false) ~= nil then\n         xtrainfo =" +
    " \"; it is a room type\"\n      end\n      pline(\"Warning: themeroom fill '\"..debug_fill\n            ..\"" +
    "' not found in themeroom_fills\"..xtrainfo, true)\n   end\nend\n\n-- called after all rooms have been gen" +
    "erated\n-- but before creating connecting corridors/doors, or filling rooms\nfunction post_themerooms_" +
    "generate()\nend\n\nfunction themeroom_fill(rm)\n   if debug_fill_idx ~= nil then\n      if is_eligible(th" +
    "emeroom_fills[debug_fill_idx], rm) then\n         themeroom_fills[debug_fill_idx].contents(rm);\n     " +
    " else\n         -- ideally this would be a debugpline, not a full pline, and offer\n         -- some m" +
    "ore context on whether it failed because of difficulty or\n         -- because of eligible function r" +
    "eturning false; the warning doesn't\n         -- necessarily mean anything.\n         pline(\"Warning: " +
    "fill '\"..themeroom_fills[debug_fill_idx].name\n               ..\"' is not eligible in room that gener" +
    "ated it\")\n      end\n      return\n   end\n   local pick = nil;\n   local total_frequency = 0;\n   for i " +
    "= 1, #themeroom_fills do\n      if (type(themeroom_fills[i]) ~= \"table\") then\n         nh.impossible(" +
    "'themeroom fill '..i..' must be a table')\n      elseif is_eligible(themeroom_fills[i], rm) then\n    " +
    "     -- Reservoir sampling: select one room from the set of eligible rooms,\n         -- which may ch" +
    "ange on different levels because of level difficulty.\n         local this_frequency;\n         if (th" +
    "emeroom_fills[i].frequency ~= nil) then\n            this_frequency = themeroom_fills[i].frequency;\n " +
    "        else\n            this_frequency = 1;\n         end\n         total_frequency = total_frequency" +
    " + this_frequency;\n         -- avoid rn2(0) if a fill has freq 0\n         if this_frequency > 0 and " +
    "nh.rn2(total_frequency) < this_frequency then\n            pick = i;\n         end\n      end\n   end\n  " +
    " if pick == nil then\n      nh.impossible('no eligible themed room fills?')\n      return\n   end\n   th" +
    "emeroom_fills[pick].contents(rm);\nend\n\n-- postprocess callback: create an engraving pointing at a lo" +
    "cation\nfunction make_dig_engraving(data)\n   local floors = selection.negate():filter_mapchar(\".\");\n " +
    "  local pos = floors:rndcoord(0);\n   local tx = data.x - pos.x - 1;\n   local ty = data.y - pos.y;\n  " +
    " local dig = \"\";\n   if (tx == 0 and ty == 0) then\n      dig = \" here\";\n   else\n      if (tx < 0 or t" +
    "x > 0) then\n         dig = string.format(\" %i %s\", math.abs(tx), (tx > 0) and \"east\" or \"west\");\n   " +
    "   end\n      if (ty < 0 or ty > 0) then\n         dig = dig .. string.format(\" %i %s\", math.abs(ty), " +
    "(ty > 0) and \"south\" or \"north\");\n      end\n   end\n   des.engraving({ coord = pos, type = \"burn\", te" +
    "xt = \"Dig\" .. dig });\nend\n\n-- postprocess callback: turn room walls into trees\nfunction make_garden_" +
    "walls(data)\n   local sel = data.sel:grow();\n   -- change walls to trees\n   des.replace_terrain({ sel" +
    "ection = sel, fromterrain=\"w\", toterrain = \"T\" });\n   -- update secret doors; attempting to change t" +
    "o AIR will set arboreal flag\n   des.replace_terrain({ selection = sel, fromterrain=\"S\", toterrain = " +
    "\"A\" });\nend\n\n-- postprocess callback: make a trap\nfunction make_a_trap(data)\n   if (data.teledest ==" +
    " 1 and data.type == \"teleport\") then\n      local locs = selection.negate():filter_mapchar(\".\");\n    " +
    "  repeat\n         data.teledest = locs:rndcoord(1);\n      until (data.teledest.x ~= data.coord.x and" +
    " data.teledest.y ~= data.coord.y);\n   end\n   des.trap(data);\nend\n\n-- called once after the whole lev" +
    "el has been generated\nfunction post_level_generate()\n   for i, v in ipairs(postprocess) do\n      v.h" +
    "andler(v.data);\n   end\n   postprocess = { };\nend\n";
